 Node3D Structure(BuildPiece p,bool preview=false){if(p.Def.Function!="structure")return BlueprintStructure(p,preview);var n=new Node3D{Position=new Vector3((float)p.X,(float)p.Y,(float)p.Z),RotationDegrees=new Vector3(0,(float)p.Yaw,0)};var d=p.Def;Color c=new Color(.39f,.29f,.19f);if(d.BaseKind==6){for(int i=0;i<12;i++)Box(n,new Vector3(0,(float)(d.H*(i+.5)/12),(float)(-d.D/2+d.D*(i+.5)/12)),new Vector3((float)d.W,(float)(d.H/12),(float)(d.D/12)),c);if(!preview){var body=new StaticBody3D();body.AddChild(new CollisionShape3D{Shape=new ConvexPolygonShape3D{Points=new[]{new Vector3(-1.5f,0,-1.5f),new Vector3(1.5f,0,-1.5f),new Vector3(-1.5f,0,1.5f),new Vector3(1.5f,0,1.5f),new Vector3(-1.5f,2.5f,1.5f),new Vector3(1.5f,2.5f,1.5f)}}});n.AddChild(body);}}else{Box(n,new Vector3(0,(float)d.H/2,0),new Vector3((float)d.W,(float)d.H,(float)d.D),c,!preview);if(d.BaseKind==2)for(int i=0;i<6;i++)Box(n,new Vector3((i-2.5f)*.48f,(float)d.H/2,-.11f),new Vector3(.025f,(float)d.H,.02f),new Color(.12f,.10f,.08f));}ArtStructure(n,new BuildPiece{Kind=d.BaseKind});if(d.Tier>1){var color=d.Tier==2?new Color(.27f,.31f,.22f):d.Tier==3?new Color(.33f,.39f,.38f):d.Tier==4?new Color(.48f,.48f,.42f):new Color(.22f,.31f,.33f);foreach(var node in n.FindChildren("*","MeshInstance3D",true,false))if(node is MeshInstance3D mesh)mesh.MaterialOverride=Material(color);}return n;}
 void SyncStructures(){ClearChildren(buildRoot);foreach(var p in game.Building.Pieces){var node=Structure(p);node.SetMeta("blueprint",p.Id??"");node.Visible=dungeon==null&&ExpeditionGame.Distance(p.X,p.Z,player.Position.X,player.Position.Z)<220;buildRoot.AddChild(node);}}
 void ClearGhost(){if(ghostMesh!=null){ghostMesh.QueueFree();ghostMesh=null;}ghost=null;}
 void UpdateGhost(){Vector3 from=camera.GlobalPosition,to=from-camera.GlobalBasis.Z*(float)reach;var query=PhysicsRayQueryParameters3D.Create(from,to);query.Exclude=new Godot.Collections.Array<Rid>{player.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(query);Vector3 point=hit.Count>0?(Vector3)hit["position"]:to;Vector3 normal=hit.Count>0?(Vector3)hit["normal"]:Vector3.Up;BuildPiece target=null;foreach(var p in game.Building.Pieces)if(p.Contains(point.X,point.Y-normal.Y*.02,point.Z,.1)){target=p;break;}var def=BuildDefinition.All[selectedBuild];if(snap&&target!=null){if(normal.Y>.5f){point.X=(float)target.X;point.Z=(float)target.Z;point.Y=(float)(target.Y+target.Def.H);}else{point+=normal*.02f;point.X+=normal.X*(float)def.W/2;point.Z+=normal.Z*(float)def.D/2;point.Y=(float)target.Y;}}else{if(snap){point.X=(float)(Math.Round(point.X/.5)*.5);point.Z=(float)(Math.Round(point.Z/.5)*.5);}point.Y=(float)game.World.Height(point.X,point.Z);}point.Y+=(float)heightBuild;ghost=new BuildPiece{Kind=selectedBuild,X=point.X,Y=point.Y,Z=point.Z,Yaw=yawBuild};placement=game.Building.Placement(ghost);if(!game.World.Playable(point.X,point.Z))placement=new BuildReport{Reason="River / world boundary"};if(ghost.Contains(player.Position.X,player.Position.Y+1,player.Position.Z,.4))placement=new BuildReport{Reason="Move clear of placement"};foreach(var p in props)if(p.Kind is 0 or 2 or 7){double lx,lz;ghost.Local(p.Position.X,p.Position.Z,out lx,out lz);if(Math.Abs(lx)<def.W/2+1&&Math.Abs(lz)<def.D/2+1)placement=new BuildReport{Reason="Blocked by environment"};}
 if(InEncounterLot(point.X,point.Z))placement=new BuildReport{Reason="Story encounter / build outside"};if(InCrashLot(point.X,point.Z))placement=new BuildReport{Reason="Road crash story site / build outside"};if(InCheckpointLot(point.X,point.Z))placement=new BuildReport{Reason="Bridge checkpoint / build outside"};if(InBirthdayLot(point.X,point.Z))placement=new BuildReport{Reason="Birthday house story site / build outside"};if(InLetterLot(point.X,point.Z))placement=new BuildReport{Reason="Church letter story site / build outside"};if(InFeverLot(point.X,point.Z))placement=new BuildReport{Reason="Side mission house / build outside"};if(InWoodlandCamp(point.X,point.Z))placement=new BuildReport{Reason="Woodland story camp / build outside"};if(InFamilyLot(point.X,point.Z))placement=new BuildReport{Reason="Willow House story site / build outside"};if(InMill(point.X,point.Z,32))placement=new BuildReport{Reason="Lumber mill combat yard / build outside"};if(placement.Valid&&game.BuildReason(ghost)!="Ready")placement=new BuildReport{Reason=game.BuildReason(ghost)};if(placement.Valid&&StaticPlacementBlocked(ghost))placement=new BuildReport{Reason="Blocked by a world structure or survivor"};if(ghostMesh==null){ghostMesh=new MeshInstance3D{CastShadow=GeometryInstance3D.ShadowCastingSetting.Off};AddChild(ghostMesh);}ghostMesh.Mesh=new BoxMesh{Size=new Vector3((float)def.W,(float)def.H,(float)def.D)};ghostMesh.Position=point+new Vector3(0,(float)def.H/2,0);ghostMesh.RotationDegrees=new Vector3(0,(float)yawBuild,0);ghostMesh.MaterialOverride=new StandardMaterial3D{AlbedoColor=placement.Valid?new Color(.2f,.8f,.4f,.35f):new Color(.9f,.2f,.2f,.35f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded};}
 void PlaceStructure(){UpdateGhost();if(CoopRequest("place",Json.Write(ghost)))return;if(!placement.Valid){game.Notice=placement.Reason;return;}if(game.PlaceBlueprint(ghost)){game.Notice="Placed "+ghost.Def.Name;SyncStructures();}}
 void RemoveStructure(){if(CoopRequest("remove"))return;Vector3 from=camera.GlobalPosition;int selected=-1;for(double t=.2;t<=reach;t+=.05){Vector3 p=from-camera.GlobalBasis.Z*(float)t;for(int i=0;i<game.Building.Pieces.Count;i++)if(game.Building.Pieces[i].Contains(p.X,p.Y,p.Z,.02)){selected=i;break;}if(selected>=0)break;}if(selected<0)return;string reason="";if(game.Change(()=>game.Building.Remove(selected,out reason)))SyncStructures();game.Notice=reason;}
 void BuildGun(){BuildHeldTool();}
 void StartReload(){if(!ExpeditionGame.IsGun(game.Craft.Weapon))return;if(CoopRequest("reload")){reloadClock=1.4*(1-game.Talent("reload")*.1)*game.SoulReload*game.PartFactor(game.Craft.Weapon,p=>p.Reload);return;}if(reloadClock<=0&&game.Craft.Reserve>0&&game.Craft.Ammo<game.Magazine){reloadClock=1.4*(1-game.Talent("reload")*.1)*game.SoulReload*game.PartFactor(game.Craft.Weapon,p=>p.Reload);Sound(2);}}
 void Shoot(){if(game.WeaponGate(game.Craft.Weapon)!="Ready"){game.Notice=game.WeaponGate(game.Craft.Weapon);return;}if(ExpeditionGame.IsMelee(game.Craft.Weapon)){BeginMelee();return;}if(shotClock>0||reloadClock>0)return;if(CoopRequest("shoot",aiming?"ads":"")){PredictGunShot();Sound(1);shotClock=ExpeditionGame.IsBow(game.Craft.Weapon)?game.SoulBowDelay:game.FireDelay;return;}bool bow=ExpeditionGame.IsBow(game.Craft.Weapon),shotgun=ExpeditionGame.Shotgun(game.Craft.Weapon);if(bow?game.Craft.Arrows<=0:game.Craft.Ammo<=0){if(!bow){if(game.Craft.Reserve<=0)game.Notice="Out of "+ExpeditionGame.AmmoNames[game.Craft.AmmoClass];else StartReload();}else game.Notice="Craft arrows in Survival research";return;}if(!game.Change(()=>{if(bow)game.Craft.Arrows--;else game.Craft.Ammo--;}))return;Sound(bow?4:1);shotClock=bow?game.SoulBowDelay:game.FireDelay;Noise(game.WeaponNoise*(bow?12*game.SoulWeaponNoise:(game.Craft.Weapon==0?55:90)*1));if(bow){LaunchArrow();game.Persist();return;}game.Handling.Shot(game.Craft.Weapon);var from=camera.GlobalPosition;int pellets=shotgun?6:1;for(int i=0;i<pellets;i++){var dir=GunDirection(i);var q=PhysicsRayQueryParameters3D.Create(from,from+dir*(shotgun?45:100));q.Exclude=new Godot.Collections.Array<Rid>{player.GetRid()};var result=GetWorld3D().DirectSpaceState.IntersectRay(q);if(result.Count==0)continue;var collider=result["collider"].AsGodotObject();var point=(Vector3)result["position"];if(IsFamilyShelf(collider as Node)){DamageFamilyShelf((int)game.Damage(false));continue;}var e=infected.Find(e=>e.Body==collider);if(e!=null){bool head=Species(e.Id)==""&&point.Y-e.Body.Position.Y>EnemyHeadHeight(e);if(IsMillBoss(e.Id))millParticipants.Add(game);MegaWeakpoint(e,point,game.Damage(head));e.Hp-=game.Damage(head)*InfectedResistance(e,head)*(IsMillBoss(e.Id)?MillDamageMultiplier(e,point):1)*(game.Talent("execution")>0&&e.Hp<e.MaxHp*.35?1.2:1);EnemyImpact(e,point,dir,head?14:8);ConfirmHit(head);ReactEnemyHit(e,head);game.TrainWeapon((head?8:4)/(double)pellets);game.Notice=head?"HEADSHOT":"HIT";if(e.Hp<=0)KillEnemy(e,true);continue;}foreach(var p in props)if(p.Kind==2&&p.Hp>0&&Distance(point,p.Position)<2.6){p.Hp-=bow?10:shotgun?12:game.Craft.Weapon==0?30:55;if(p.Hp<=0)ExplodeCar(p);break;}BulletMark(point,(Vector3)result["normal"]);}game.Persist();}
 void ExplodeCar(WorldProp p){if(!game.Change(()=>game.World.Changes.Burn(p.Id)))return;p.Hp=0;HearNoise(p.Position,125);CoopBlast(p.Position);foreach(var e in infected.ToArray()){float d=Distance(e.Body.Position,p.Position);if(d<10){e.Hp-=180*(1-d/10);if(e.Hp<=0)KillEnemy(e);}}if(Dog.Rescued&&!Dog.Dead&&DogPresent&&Distance(DogPoint,p.Position)<10)HurtRescueDog(180*(1-Distance(DogPoint,p.Position)/10));float near=Distance(player.Position,p.Position);if(near<9){game.Life.Health-=100*(1-near/9);game.LastDamage=game.Clock;}foreach(var child in p.Node.GetChildren())if(child is MeshInstance3D m)m.MaterialOverride=Material(new Color(.09f,.10f,.09f));game.Persist();game.Notice="Wreck exploded / noise attracted infected";if(game.Life.Health<=0)Die();}
 void AddEnemy(string id,double x,double z,int tier,int night=0){if(!CoopClient&&ExpeditionThreatEcology.Natural(id)&&id==ExpeditionThreat.SpawnKey(id)){if(game.Skills.Defeated.Contains(id)||infected.Exists(e=>ExpeditionThreat.SpawnKey(e.Id)==id))return;id=ExpeditionThreatEcology.Stamp(id,tier,night,dungeon==null?ExpeditionThreatEcology.Surface(game.World,x,z):ExpeditionThreatEcology.Dungeon(dungeon.Id),dungeon!=null);}if(IsCampaignBoss(id)){AddCampaignBoss(id,x,z);return;}if(IsMillBoss(id)){AddMillBoss(id,x,z);return;}if(!id.StartsWith("brood/worm/")&&!id.StartsWith("boss/campaign/")&&!IsEncounterGuardian(id)&&!IsCheckpointGuard(id)&&!IsSammy(id)&&!id.StartsWith("story/fever/")&&!id.StartsWith("story/woodland/")&&!IsTownGuard(id)&&!IsContentEnemy(id)&&!IsSettlementActor(id)&&!IsSettlementMission(id)&&!CoopClient&&dungeon==null&&!OutdoorFree(x,z))return;if(game.Skills.Defeated.Contains(id)||game.Skills.Defeated.Contains(ExpeditionThreat.SpawnKey(id))||infected.Exists(e=>ExpeditionThreat.SpawnKey(e.Id)==ExpeditionThreat.SpawnKey(id)))return;var body=new CharacterBody3D{Name="Infected",Position=dungeon==null?Ground(x,z):new Vector3((float)x,0,(float)z),FloorSnapLength=.4f};body.AddChild(new CollisionShape3D{Shape=new CapsuleShape3D{Radius=Species(id)=="rabbit"?.14f:Species(id)!=""?.30f:.35f,Height=Species(id)=="rabbit"?.42f:Species(id)=="deer"?1.3f:Species(id)!=""?.80f:1.8f},Position=new Vector3(0,Species(id)=="rabbit"?.21f:Species(id)=="deer"?.65f:Species(id)!=""?.40f:.9f,0)});var visual=new Node3D();body.AddChild(visual);if(!CoopHost||Distance(body.Position,HostPosition)<160)ActorArt(visual,id,tier,night);if(id==FamilyInfectedId)visual.Scale=new(.72f,.95f,.72f);if(IsSammy(id)){var shape=body.GetChild<CollisionShape3D>(0);shape.Shape=new CapsuleShape3D{Radius=.23f,Height=1.16f};shape.Position=new(0,.58f,0);}AddChild(body);infected.Add(new Infected{BossState=IsSammy(id)?Birthday.CakeTouched?"birthday-awake":"birthday-seated":"",Id=id,Body=body,Visual=visual,Tier=tier,Night=night,Hp=IsCheckpointGuard(id)?75:IsSammy(id)?35:Species(id)=="rabbit"?15:Species(id)=="deer"?40:Species(id)=="boar"?70:Species(id)=="dog"?55+Math.Max(0,tier-2)*12:night==1?110:night==2?180:45+tier*20,Home=body.Position,Target=body.Position});infected[^1].MaxHp=infected[^1].Hp;ConfigureSpecial(infected[^1]);}
 bool OutdoorFree(double x,double z){if(InEncounterLot(x,z)||InCrashLot(x,z)||InCheckpointLot(x,z)||InBirthdayLot(x,z)||InLetterLot(x,z)||InFeverLot(x,z)||InFamilyLot(x,z))return false;foreach(var stop in props)if(stop.Kind==16&&ExpeditionGame.Distance(stop.Position.X,stop.Position.Z,x,z)<3.5)return false;if(InMill(x,z,33))return false;if(!game.World.Playable(x,z)||StoryObstacle(x,z))return false;double bx=Math.Floor(x/32)*32+16,bz=Math.Floor(z/32)*32+16;if(game.World.BuildingCell(bx,bz)&&Math.Abs(x-bx)<game.World.BuildingHalf(bx,bz)+.4&&Math.Abs(z-bz)<game.World.BuildingHalf(bx,bz)+.4)return false;foreach(var p in props)if(p.Kind is 0 or 7 or 2 or 10){float r=p.Kind==0?.9f:p.Kind==7?1.3f:p.Kind==10?1.2f:2.7f;if(ExpeditionGame.Distance(x,z,p.Position.X,p.Position.Z)<r)return false;}return game.Building.Free(x,game.World.Height(x,z),z);}
 void SpawnInfected(){SpawnFauna();if(CoopHost)SpawnCoopInfected();else SpawnSoloHabitats();}
 bool Sight(Infected e,float distance){if(distance>(e.Memory>0?24:game.VisualRange))return false;var from=e.Body.Position+new Vector3(0,1.5f,0);var delta=camera.GlobalPosition-from;if(distance>(game.Sneaking?1.5:4)&&(-e.Body.Basis.Z).Dot(delta.Normalized())<.25)return false;var q=PhysicsRayQueryParameters3D.Create(from,camera.GlobalPosition);q.Exclude=new Godot.Collections.Array<Rid>{e.Body.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);return hit.Count==0||hit["collider"].AsGodotObject()==player;}
 void TickEnemies(double dt){TickContentAtlas(dt);TickRescueDog(dt);TickLivingCommunities(dt);TickBrood(dt);TickDrone(dt);TickCheckpoint(dt);TickLastLetter(dt);TickFeverStory(dt);TickWoodlandTraps();TickCommunity(dt);PursuitExclusions();TickScavengeTraps(dt);TickMillPools(dt);if(CoopHost){TickCoopEnemies(dt);return;}TickSoloEnemies(dt);}void TickSoloEnemies(double dt){foreach(var e in infected.ToArray()){if(!infected.Contains(e))continue;if(TickSettlementActor(e,dt))continue;if(TickTownGuard(e,dt))continue;if(TickEncounterGuardian(e,dt))continue;if(TickCheckpointGuard(e,dt))continue;if(TickBirthdayEnemy(e,dt))continue;if(TickWoodlandKneeler(e))continue;if(TickFamilyLunge(e,dt))continue;if(IsCampaignBoss(e.Id))TickCampaignBoss(e,dt);else if(TickSpecialInfected(e,dt))continue;else if(IsMillBoss(e.Id))TickMillBoss(e,dt);else if(Species(e.Id)!="")TickAnimal(e,dt);else TickZombie(e,dt);}}
 void KillEnemy(Infected e,bool train=false){if(!infected.Contains(e))return;ContentEnemyDeath(e);if(PrimeCinder(e))return;if(IsMegaNest(e.Id)){DeathRemains(e);RemoveEnemy(e);game.Notice="BROOD NEST DESTROYED / smaller next wave";return;}if(IsSettlementActor(e.Id)||IsSettlementMission(e.Id)){SettlementCombatDeath(e);return;}if(IsTownGuard(e.Id)){TownGuardDeath(e);return;}if(IsCampaignBoss(e.Id)){DefeatCampaignBoss(e);return;}if(InfectedKind(e)=="bloater")QueueBrood(e);if(InfectedKind(e)=="worm"){if(!game.Skills.Defeated.Contains(e.Id)){game.Skills.Defeated.Add(e.Id);game.Career.Gain(3);if(train)game.TrainWeapon(18);}ImpactParticles(e.Body.Position,new(.46f,.52f,.15f),5,.04f);RemoveEnemy(e);game.Persist();return;}if(IsCheckpointGuard(e.Id))StartCheckpointFight();if(IsMillBoss(e.Id)){DefeatMillBoss(e);return;}EnemyImpact(e,e.Body.GlobalPosition+Vector3.Up*.65f,Vector3.Up,24);DeathRemains(e);if(Species(e.Id)!="")AnimalLoot(e);else ClaimThreatKill(e,train);RemoveEnemy(e);}
 void RemoveEnemy(Infected e){RemoveChild(e.Body);e.Body.QueueFree();infected.Remove(e);}
 void ClearEnemies(){cinderOwners.Clear();foreach(var p in megaProjectiles)p.Mesh?.QueueFree();megaProjectiles.Clear();megaGrowthDamage.Clear();ClearChainCombat();ClearBrood();campaignParticipants.Clear();ClearMillPools();foreach(var e in infected.ToArray())RemoveEnemy(e);spawned.Clear();spawnClock=0;}
